		public static global::System.Collections.Generic.List<global::Pml.PokePara.PokemonParam> CreatePokemonParamsByBattle() {
            var party = BattleViewCore.Instance.ViewSystem.GetBattleParty_Self();
            _pokemonParamMappings.Clear();
            byte memberCount = party.GetMemberCount();
            var pokemonParams = new List<PokemonParam>();
            byte clientId = BattleViewCore.Instance.ViewSystem.GetClientID();
            for (byte i = 0; i < memberCount; i++)
            {
                var battlePokemonParam = party.GetMemberData(i);
                var pokemonParam = CreatePokemonParamByBattle(battlePokemonParam);
                pokemonParams.Add(pokemonParam);
                _pokemonParamMappings.Add(new PokemonParamMapping()
                {
                    battlePokemonParam = battlePokemonParam,
                    pokemonParam = pokemonParam,
                    clientId = clientId,
                });
            }

            var friendParty = GetMultiPlayerFriendParty();
            if (friendParty != null)
            {
                byte friendClientId = BattleViewCore.Instance.ViewSystem.GetFriendCleintID();
                byte friendMemberCount = friendParty.GetMemberCount();
                for (byte i = 0; i < friendMemberCount; i++)
                {
                    var battlePokemonParam = friendParty.GetMemberData(i);
                    var pokemonParam = CreatePokemonParamByBattle(battlePokemonParam);
                    if (PlayerWork.config.GetValue(ConfigID.ShowNickname) != 0)
                        pokemonParam.SetDefaultNickName();
                    pokemonParams.Add(pokemonParam);
                    _pokemonParamMappings.Add(new PokemonParamMapping()
                    {
                        battlePokemonParam = battlePokemonParam,
                        pokemonParam = pokemonParam,
                        clientId = friendClientId,
                    });
                }
            }

            return pokemonParams;
        }
