                                    cache.sprite = sprite;
                                    _cacheSpritePokemons.MoveLast(cache, null);
                                    onComplete.Invoke(sprite);
                                }
                                break;

                            case RequestEventType.Complete:
                                AssetManager.UnloadAssetBundle(assetBundleName);
                                break;
                        }
                    });
                    return;
                }

                onComplete.Invoke(null);
            }
            else
            {
                _cacheSpritePokemons.MoveLast(cache, x =>
                {
                    x.Destroy();
                    return true;
                });

                if (cache.sprite != null)
                    onComplete.Invoke(cache.sprite);
                else
                    Sequencer.Start(OpCompleteSprite<int>(cache, onComplete));
            }

            IEnumerator OpCompleteSprite<T>(CacheSpritePokemonParam cache_, UnityAction<Sprite> onComplete_)
            {
                while (cache_.sprite == null)
                    yield return null;

                onComplete_.Invoke(cache_.sprite);
            }
        }
