		internal void _CaptureBlueImage(bool enabled) {
            // @017ab0e0: the packet C names the static `STATIC_0x38(Graphics)`; the listing loads SmartPoint.Rendering.DepthOfField_TypeInfo
            // (+0x38 = DepthOfField.instance, +0x78 = blurredRT = the inlined `strongerBlurTexture` getter)
            if (SmartPoint.Rendering.DepthOfField.instance == null)
                return;

            var blurTexture = SmartPoint.Rendering.DepthOfField.instance.strongerBlurTexture;
            if (blurTexture == null)
                return;

            _blurBgParam.isCapture = enabled;
            if (!enabled)
                return;

            if (_blurBgParam.blankTexture == null)
            {
                var texture = new Texture2D(2, 2, TextureFormat.ARGB32, false);
                var color = new Color32(0, 0, 0, 1);
                texture.SetPixels32(new Color32[] { color, color, color, color }, 0);
                texture.Apply(false);
                _blurBgParam.blankTexture = texture;
            }

            // shipped: blits into `captureBlurTexture`, which nothing in UIManager ever assigns
            Graphics.Blit(blurTexture, _blurBgParam.captureBlurTexture);
